import { motion, AnimatePresence } from "framer-motion";
import { useState, useEffect } from "react";
import { useNavigate, useLocation } from "react-router-dom";
import { Menu, X, ArrowRight } from "lucide-react";

const LOGO =
  "https://customer-assets.emergentagent.com/job_power-solutions-149/artifacts/fddzfu5o_download%20%282%29.png";

const NAV_ITEMS = [
  { label: "Home", type: "route", path: "/" },
  { label: "Services", type: "route", path: "/services" },
  { label: "Our Work", type: "route", path: "/our-work" },
  { label: "Contact", type: "route", path: "/contact" },
];

export const Header = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 40);
    onScroll();
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  // Lock body scroll when menu is open
  useEffect(() => {
    document.body.style.overflow = menuOpen ? "hidden" : "";
    return () => {
      document.body.style.overflow = "";
    };
  }, [menuOpen]);

  const handleNav = (item) => {
    setMenuOpen(false);
    if (item.type === "route") {
      navigate(item.path);
      return;
    }
    if (location.pathname !== "/") {
      navigate("/", { state: { scrollTo: item.id } });
    } else {
      document.getElementById(item.id)?.scrollIntoView({ behavior: "smooth" });
    }
  };

  return (
    <motion.header
      initial={{ opacity: 0, y: -20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.7, ease: [0.22, 1, 0.36, 1] }}
      data-testid="site-header"
      className={`fixed top-0 left-0 z-50 flex w-full items-center justify-between px-5 backdrop-blur-xl transition-all duration-300 md:px-12 lg:px-16 ${
        scrolled || menuOpen
          ? "h-14 border-b border-white/10 bg-black/90 shadow-lg shadow-black/30 md:h-16"
          : "h-16 border-b border-white/5 bg-black/30 md:h-20"
      }`}
    >
      {/* Logo */}
      <button
        onClick={() => {
          setMenuOpen(false);
          navigate("/");
        }}
        data-testid="header-logo"
        className="flex items-center"
      >
        <img
          src={LOGO}
          alt="Carter Electric"
          className={`w-auto transition-all duration-300 ${
            scrolled || menuOpen ? "h-12 md:h-16" : "h-14 md:h-24"
          }`}
          style={{ mixBlendMode: "lighten" }}
        />
      </button>

      {/* Center nav (desktop) */}
      <nav className="hidden items-center gap-1 md:flex">
        {NAV_ITEMS.map((item) => (
          <button
            key={item.label}
            onClick={() => handleNav(item)}
            data-testid={`nav-${item.label.toLowerCase().replace(/\s+/g, "-")}`}
            className="rounded-full px-5 py-2 font-[IBM_Plex_Sans] text-sm font-medium text-white/75 transition-all duration-300 hover:bg-white/10 hover:text-white"
          >
            {item.label}
          </button>
        ))}
      </nav>

      {/* Right CTA (desktop) */}
      <button
        onClick={() => navigate("/contact")}
        data-testid="header-contact-btn"
        className="hidden border border-[#FF5C00] bg-[#FF5C00] px-5 py-2.5 font-[IBM_Plex_Sans] text-sm font-semibold uppercase tracking-wider text-black transition-all duration-300 hover:bg-transparent hover:text-[#FF5C00] md:inline-block"
      >
        Contact
      </button>

      {/* Hamburger (mobile) */}
      <button
        onClick={() => setMenuOpen((o) => !o)}
        data-testid="mobile-menu-toggle"
        aria-label="Toggle menu"
        className="flex h-10 w-10 items-center justify-center text-white md:hidden"
      >
        {menuOpen ? <X className="h-7 w-7" /> : <Menu className="h-7 w-7" />}
      </button>

      {/* Mobile menu drawer */}
      <AnimatePresence>
        {menuOpen && (
          <motion.nav
            key="mobile-menu"
            initial={{ opacity: 0, y: -12 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -12 }}
            transition={{ duration: 0.25, ease: [0.22, 1, 0.36, 1] }}
            data-testid="mobile-menu"
            className="absolute left-0 top-full w-full border-b border-white/10 bg-black/95 px-5 py-4 backdrop-blur-xl md:hidden"
          >
            <div className="flex flex-col">
              {NAV_ITEMS.map((item) => (
                <button
                  key={item.label}
                  onClick={() => handleNav(item)}
                  data-testid={`nav-mobile-${item.label.toLowerCase().replace(/\s+/g, "-")}`}
                  className="border-b border-white/5 py-4 text-left font-[Outfit] text-lg font-semibold text-white/90 transition-colors hover:text-[#FF5C00]"
                >
                  {item.label}
                </button>
              ))}
              <button
                onClick={() => handleNav({ type: "route", path: "/contact" })}
                data-testid="mobile-menu-cta"
                className="mt-4 inline-flex items-center justify-center gap-2 bg-[#FF5C00] px-5 py-3.5 font-[IBM_Plex_Sans] text-sm font-semibold uppercase tracking-wider text-black"
              >
                Get a Free Quote
                <ArrowRight className="h-4 w-4" />
              </button>
            </div>
          </motion.nav>
        )}
      </AnimatePresence>
    </motion.header>
  );
};

export default Header;
