import { useState, useRef, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import axios from "axios";
import { MessageSquare, X, Send, Loader2 } from "lucide-react";

const API = `${process.env.REACT_APP_BACKEND_URL}/api`;

function makeSessionId() {
  return "sess-" + Math.random().toString(36).slice(2) + Date.now().toString(36);
}

const GREETING =
  "Hi! I'm Carter Electric's AI assistant. Ask me about our services, service areas, or getting a quote.";

export default function ChatWidget() {
  const [open, setOpen] = useState(false);
  const [sessionId] = useState(makeSessionId);
  const [messages, setMessages] = useState([
    { role: "assistant", content: GREETING },
  ]);
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);
  const scrollRef = useRef(null);
  const [isMobile, setIsMobile] = useState(false);
  const [vp, setVp] = useState(() => ({
    top: 0,
    height: typeof window !== "undefined" ? window.innerHeight : 800,
  }));

  // Track mobile breakpoint
  useEffect(() => {
    const mq = window.matchMedia("(max-width: 767px)");
    const update = () => setIsMobile(mq.matches);
    update();
    mq.addEventListener("change", update);
    return () => mq.removeEventListener("change", update);
  }, []);

  // Track the visual viewport (shrinks when the keyboard opens)
  useEffect(() => {
    const vv = window.visualViewport;
    if (!vv) return;
    const onChange = () => setVp({ top: vv.offsetTop, height: vv.height });
    onChange();
    vv.addEventListener("resize", onChange);
    vv.addEventListener("scroll", onChange);
    return () => {
      vv.removeEventListener("resize", onChange);
      vv.removeEventListener("scroll", onChange);
    };
  }, []);

  // Lock background scroll while chat is open on mobile
  useEffect(() => {
    if (isMobile && open) {
      document.body.style.overflow = "hidden";
    } else {
      document.body.style.overflow = "";
    }
    return () => {
      document.body.style.overflow = "";
    };
  }, [isMobile, open]);

  useEffect(() => {
    scrollRef.current?.scrollTo({ top: scrollRef.current.scrollHeight, behavior: "smooth" });
  }, [messages, loading, open, vp.height]);

  const send = async (e) => {
    e?.preventDefault();
    const text = input.trim();
    if (!text || loading) return;
    setInput("");
    setMessages((m) => [...m, { role: "user", content: text }]);
    setLoading(true);
    try {
      const res = await axios.post(`${API}/chat`, {
        session_id: sessionId,
        message: text,
      });
      setMessages((m) => [...m, { role: "assistant", content: res.data.reply }]);
    } catch (err) {
      setMessages((m) => [
        ...m,
        {
          role: "assistant",
          content:
            "Sorry, I couldn't respond just now. Please call (416) 555-1234 or use the Contact page.",
        },
      ]);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed bottom-20 right-4 z-[60] flex flex-col items-end md:bottom-24 md:right-5">
      <AnimatePresence>
        {open && (
          <motion.div
            initial={isMobile ? { y: "100%" } : { opacity: 0, y: 20, scale: 0.96 }}
            animate={isMobile ? { y: 0 } : { opacity: 1, y: 0, scale: 1 }}
            exit={isMobile ? { y: "100%" } : { opacity: 0, y: 20, scale: 0.96 }}
            transition={{ duration: 0.3, ease: [0.22, 1, 0.36, 1] }}
            data-testid="chat-window"
            style={
              isMobile
                ? { position: "fixed", left: 0, right: 0, top: vp.top, height: vp.height, width: "100%", zIndex: 70 }
                : undefined
            }
            className={`flex flex-col overflow-hidden border-white/10 bg-[#0F0F0F] shadow-2xl ${
              isMobile
                ? "border-0"
                : "mb-3 h-[58vh] max-h-[440px] w-[calc(100vw-2rem)] max-w-[360px] rounded-lg border"
            }`}
          >
            {/* Header */}
            <div className="flex items-center justify-between border-b border-white/10 bg-[#141414] px-4 py-3">
              <div className="flex items-center gap-2.5">
                <span className="flex h-7 w-7 items-center justify-center rounded-sm bg-[#FF5C00]">
                  <MessageSquare className="h-4 w-4 text-black" />
                </span>
                <div>
                  <div className="flex items-center gap-2 font-[Outfit] text-sm font-bold text-white">
                    Carter Electric
                    <span className="rounded-full bg-[#FF5C00]/15 px-1.5 py-0.5 font-[IBM_Plex_Sans] text-[9px] font-semibold uppercase tracking-wider text-[#FF5C00]">
                      AI
                    </span>
                  </div>
                  <div className="flex items-center gap-1.5 font-[IBM_Plex_Sans] text-[11px] text-white/45">
                    <span className="h-1.5 w-1.5 rounded-full bg-green-500" />
                    AI Assistant · replies instantly
                  </div>
                </div>
              </div>
              <button
                onClick={() => setOpen(false)}
                data-testid="chat-close"
                className="text-white/50 transition-colors hover:text-white"
              >
                <X className="h-5 w-5" />
              </button>
            </div>

            {/* Messages */}
            <div
              ref={scrollRef}
              data-testid="chat-messages"
              className="no-scrollbar flex-1 space-y-3 overflow-y-auto p-4"
            >
              {messages.map((m, i) => (
                <div
                  key={i}
                  className={`flex ${m.role === "user" ? "justify-end" : "justify-start"}`}
                >
                  <div
                    data-testid={`chat-msg-${m.role}`}
                    className={`max-w-[80%] rounded-lg px-3.5 py-2 font-[IBM_Plex_Sans] text-sm leading-relaxed ${
                      m.role === "user"
                        ? "bg-[#FF5C00] text-black"
                        : "bg-[#1d1d1d] text-white/85"
                    }`}
                  >
                    {m.content}
                  </div>
                </div>
              ))}
              {loading && (
                <div className="flex justify-start">
                  <div className="flex items-center gap-2 rounded-lg bg-[#1d1d1d] px-3.5 py-2.5">
                    <Loader2 className="h-4 w-4 animate-spin text-[#FF5C00]" />
                    <span className="font-[IBM_Plex_Sans] text-xs text-white/50">
                      Typing...
                    </span>
                  </div>
                </div>
              )}
            </div>

            {/* Input */}
            <form
              onSubmit={send}
              className="flex items-center gap-2 border-t border-white/10 bg-[#141414] p-3"
            >
              <input
                value={input}
                onChange={(e) => setInput(e.target.value)}
                data-testid="chat-input"
                placeholder="Type your question..."
                className="flex-1 rounded-full border border-white/15 bg-[#0F0F0F] px-4 py-2 font-[IBM_Plex_Sans] text-sm text-white placeholder-white/40 focus:border-[#FF5C00] focus:outline-none"
              />
              <button
                type="submit"
                disabled={loading || !input.trim()}
                data-testid="chat-send"
                className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-[#FF5C00] text-black transition-all duration-300 hover:bg-white disabled:opacity-40"
              >
                <Send className="h-4 w-4" />
              </button>
            </form>
            <div className="bg-[#141414] pb-2 text-center font-[IBM_Plex_Sans] text-[10px] text-white/30">
              AI assistant · may be inaccurate. Confirm details with us.
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Toggle button */}
      <button
        onClick={() => setOpen((o) => !o)}
        data-testid="chat-toggle"
        aria-label="Open chat"
        className={`flex h-14 w-14 items-center justify-center rounded-full bg-[#FF5C00] text-black shadow-lg transition-all duration-300 hover:scale-105 hover:bg-white ${
          isMobile && open ? "hidden" : "flex"
        }`}
      >
        {open ? <X className="h-6 w-6" /> : <MessageSquare className="h-6 w-6" />}
      </button>
    </div>
  );
}

