import { useState } from "react";
import { motion } from "framer-motion";
import axios from "axios";
import { toast } from "sonner";
import {
  Phone,
  Mail,
  MapPin,
  Clock,
  Send,
  Loader2,
  CheckCircle2,
} from "lucide-react";

const API = `${process.env.REACT_APP_BACKEND_URL}/api`;

const fade = {
  hidden: { opacity: 0, y: 24 },
  show: { opacity: 1, y: 0, transition: { duration: 0.6, ease: [0.22, 1, 0.36, 1] } },
};

const SERVICES = [
  "Residential Electrical",
  "Commercial Electrical",
  "Repairs & Troubleshooting",
  "Panel & Service Upgrades",
  "EV Charger Installation",
  "Emergency Service",
  "Other",
];

const CONTACT_INFO = [
  { icon: Phone, label: "Call Us", value: "(416) 555-1234", href: "tel:+14165551234" },
  { icon: Mail, label: "Email Us", value: "info@carterelectric.ca", href: "mailto:info@carterelectric.ca" },
  { icon: MapPin, label: "Service Area", value: "Greater Toronto Area", href: null },
  { icon: Clock, label: "Hours", value: "24/7 Emergency Service", href: null },
];

export default function ContactPage() {
  const [form, setForm] = useState({
    name: "",
    email: "",
    phone: "",
    service: "",
    message: "",
  });
  const [submitting, setSubmitting] = useState(false);
  const [submitted, setSubmitted] = useState(false);

  const handleChange = (e) =>
    setForm({ ...form, [e.target.name]: e.target.value });

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!form.name || !form.email || !form.message) {
      toast.error("Please fill in your name, email, and message.");
      return;
    }
    setSubmitting(true);
    try {
      await axios.post(`${API}/contact`, form);
      setSubmitted(true);
      toast.success("Thanks! We'll be in touch shortly.");
      setForm({ name: "", email: "", phone: "", service: "", message: "" });
    } catch (err) {
      toast.error("Something went wrong. Please try again or call us.");
    } finally {
      setSubmitting(false);
    }
  };

  const inputClass =
    "w-full rounded-sm border border-white/15 bg-[#141414] px-4 py-3 font-[IBM_Plex_Sans] text-sm text-white placeholder-white/40 transition-colors duration-300 focus:border-[#FF5C00] focus:outline-none";

  return (
    <main data-testid="contact-page" className="w-full bg-[#0A0A0A]">
      {/* Header band */}
      <section className="w-full px-6 pb-10 pt-28 md:px-12 md:pt-36 lg:px-24">
        <motion.div
          initial="hidden"
          animate="show"
          transition={{ staggerChildren: 0.1 }}
          className="mx-auto max-w-6xl"
        >
          <motion.p
            variants={fade}
            className="mb-3 font-[IBM_Plex_Sans] text-xs font-semibold uppercase tracking-[0.3em] text-[#FF5C00] md:text-sm"
          >
            Contact
          </motion.p>
          <motion.h1
            variants={fade}
            data-testid="contact-heading"
            className="max-w-3xl font-[Outfit] text-3xl font-extrabold leading-tight tracking-tight text-white sm:text-4xl md:text-5xl lg:text-6xl"
          >
            Let's get your project <span className="text-[#FF5C00]">powered up.</span>
          </motion.h1>
          <motion.p
            variants={fade}
            className="mt-5 max-w-xl font-[IBM_Plex_Sans] text-base leading-relaxed text-white/70 md:text-lg"
          >
            Tell us what you need and we'll get back to you with a free,
            no-obligation quote. For emergencies, give us a call any time.
          </motion.p>
        </motion.div>
      </section>

      {/* Content */}
      <section className="w-full px-6 pb-20 md:px-12 md:pb-28 lg:px-24">
        <div className="mx-auto grid max-w-6xl grid-cols-1 gap-10 lg:grid-cols-5 lg:gap-14">
          {/* Info column */}
          <motion.div
            initial="hidden"
            whileInView="show"
            viewport={{ once: true, amount: 0.2 }}
            transition={{ staggerChildren: 0.08 }}
            className="lg:col-span-2"
          >
            <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-1">
              {CONTACT_INFO.map((info) => {
                const Inner = (
                  <div className="flex items-start gap-4 rounded-sm border border-white/10 bg-[#121212] p-5 transition-colors duration-300 hover:border-[#FF5C00]/40">
                    <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-sm bg-[#FF5C00]/10">
                      <info.icon className="h-5 w-5 text-[#FF5C00]" />
                    </div>
                    <div>
                      <div className="font-[IBM_Plex_Sans] text-xs font-medium uppercase tracking-wider text-white/45">
                        {info.label}
                      </div>
                      <div className="mt-1 font-[Outfit] text-base font-semibold text-white">
                        {info.value}
                      </div>
                    </div>
                  </div>
                );
                return (
                  <motion.div
                    key={info.label}
                    variants={fade}
                    data-testid={`contact-info-${info.label.toLowerCase().replace(/\s+/g, "-")}`}
                  >
                    {info.href ? (
                      <a href={info.href} className="block">
                        {Inner}
                      </a>
                    ) : (
                      Inner
                    )}
                  </motion.div>
                );
              })}
            </div>
          </motion.div>

          {/* Form column */}
          <motion.div
            initial={{ opacity: 0, y: 24 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true, amount: 0.2 }}
            transition={{ duration: 0.6, ease: [0.22, 1, 0.36, 1] }}
            className="lg:col-span-3"
          >
            {submitted ? (
              <div
                data-testid="contact-success"
                className="flex h-full flex-col items-center justify-center rounded-sm border border-[#FF5C00]/30 bg-[#121212] p-10 text-center"
              >
                <CheckCircle2 className="mb-4 h-14 w-14 text-[#FF5C00]" />
                <h3 className="font-[Outfit] text-2xl font-bold text-white">
                  Message sent!
                </h3>
                <p className="mt-2 max-w-sm font-[IBM_Plex_Sans] text-sm text-white/60">
                  Thanks for reaching out to Carter Electric. We'll get back to
                  you as soon as possible.
                </p>
                <button
                  onClick={() => setSubmitted(false)}
                  data-testid="contact-send-another"
                  className="mt-6 border border-white/20 px-5 py-2.5 font-[IBM_Plex_Sans] text-sm font-semibold uppercase tracking-wider text-white transition-all duration-300 hover:border-[#FF5C00] hover:text-[#FF5C00]"
                >
                  Send another
                </button>
              </div>
            ) : (
              <form
                onSubmit={handleSubmit}
                data-testid="contact-form"
                className="rounded-sm border border-white/10 bg-[#121212] p-6 md:p-8"
              >
                <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
                  <div>
                    <label className="mb-2 block font-[IBM_Plex_Sans] text-xs font-medium uppercase tracking-wider text-white/55">
                      Name *
                    </label>
                    <input
                      name="name"
                      value={form.name}
                      onChange={handleChange}
                      data-testid="contact-input-name"
                      placeholder="John Smith"
                      className={inputClass}
                    />
                  </div>
                  <div>
                    <label className="mb-2 block font-[IBM_Plex_Sans] text-xs font-medium uppercase tracking-wider text-white/55">
                      Email *
                    </label>
                    <input
                      name="email"
                      type="email"
                      value={form.email}
                      onChange={handleChange}
                      data-testid="contact-input-email"
                      placeholder="john@example.com"
                      className={inputClass}
                    />
                  </div>
                  <div>
                    <label className="mb-2 block font-[IBM_Plex_Sans] text-xs font-medium uppercase tracking-wider text-white/55">
                      Phone
                    </label>
                    <input
                      name="phone"
                      value={form.phone}
                      onChange={handleChange}
                      data-testid="contact-input-phone"
                      placeholder="(416) 555-0000"
                      className={inputClass}
                    />
                  </div>
                  <div>
                    <label className="mb-2 block font-[IBM_Plex_Sans] text-xs font-medium uppercase tracking-wider text-white/55">
                      Service Needed
                    </label>
                    <select
                      name="service"
                      value={form.service}
                      onChange={handleChange}
                      data-testid="contact-input-service"
                      className={`${inputClass} cursor-pointer`}
                    >
                      <option value="">Select a service</option>
                      {SERVICES.map((s) => (
                        <option key={s} value={s} className="bg-[#141414]">
                          {s}
                        </option>
                      ))}
                    </select>
                  </div>
                </div>

                <div className="mt-4">
                  <label className="mb-2 block font-[IBM_Plex_Sans] text-xs font-medium uppercase tracking-wider text-white/55">
                    Message *
                  </label>
                  <textarea
                    name="message"
                    value={form.message}
                    onChange={handleChange}
                    data-testid="contact-input-message"
                    rows={5}
                    placeholder="Tell us about your project..."
                    className={`${inputClass} resize-none`}
                  />
                </div>

                <button
                  type="submit"
                  disabled={submitting}
                  data-testid="contact-submit"
                  className="group mt-6 inline-flex w-full items-center justify-center gap-2 bg-[#FF5C00] px-6 py-3.5 font-[IBM_Plex_Sans] text-sm font-semibold uppercase tracking-wider text-black transition-all duration-300 hover:bg-white disabled:cursor-not-allowed disabled:opacity-60 sm:w-auto"
                >
                  {submitting ? (
                    <>
                      <Loader2 className="h-4 w-4 animate-spin" />
                      Sending...
                    </>
                  ) : (
                    <>
                      Send Message
                      <Send className="h-4 w-4 transition-transform duration-300 group-hover:translate-x-1" />
                    </>
                  )}
                </button>
              </form>
            )}
          </motion.div>
        </div>
      </section>
    </main>
  );
}
